import React from 'react';
import { useOutletContext } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';

const DynamicCloudSub = ({ index, title }) => {
  const context = useOutletContext();
  const cloudData = context?.cloud?.data;
  const pData = cloudData ? cloudData[index] : null;

  return (
    <div className="workspace-container">
      <ProjectNavbar basePath="cloud" links={["Fleet", "Docker", "Terraform", "CI/CD"]} />
      <div className="summary-box">
        <h3>{title}</h3>
        <p>{pData ? `Status: ${pData.status}` : "No data. Sync from Dashboard."}</p>
        {pData && <pre>{JSON.stringify(pData, null, 2)}</pre>}
      </div>
    </div>
  );
};

// Use this for each file, passing the index (0, 1, 2, or 3)
export default DynamicCloudSub;
